const input = $input.first()?.json || {};
const body = input.body ?? input;
const candidate = body.data ?? body.message ?? body;

const messageId = candidate.message_id || candidate.name || candidate.docname || body.message_id || input.message_id || '';
const integration = candidate.integration || candidate.whatsapp_integration || body.integration || input.integration || '';
const customerPhone = candidate.from_phone || candidate.customer_phone || body.from_phone || body.customer_phone || '';
const customerName = candidate.customer_name || body.customer_name || '';
const customerMessage = candidate.text_content || candidate.message_text || candidate.customer_message || body.text_content || body.message_text || '';
const messageType = candidate.message_type || body.message_type || 'text';
const imageId = candidate.image_id || body.image_id || '';

if (!messageId) {
  throw new Error('ERPNext webhook payload must include message_id');
}

return {
  json: {
    message_id: messageId,
    integration,
    customer_phone: customerPhone,
    customer_name: customerName,
    customer_message: customerMessage,
    message_type: messageType,
    image_id: imageId,
    received_at: new Date().toISOString()
  }
};

const incoming = $('Normalize ERPNext Payload').first().json;
const response = $input.first()?.json || {};

if (response.error) {
  return {
    json: {
      ...incoming,
      workflow_error: `Failed to fetch WhatsApp Message: ${response.error.message || 'unknown error'}`
    }
  };
}

const message = response.data || response.message || response;

return {
  json: {
    ...incoming,
    message_id: message.name || incoming.message_id,
    integration: message.integration || incoming.integration,
    customer_phone: message.from_phone || incoming.customer_phone,
    customer_name: message.customer_name || incoming.customer_name,
    customer_message: message.text_content || incoming.customer_message,
    message_type: message.message_type || incoming.message_type || 'text',
    image_id: message.image_id || incoming.image_id,
    message_doc: message
  }
};

const incoming = $('Merge Message Context').first().json;
const response = $input.first()?.json || {};

if (response.error) {
  return {
    json: {
      ...incoming,
      workflow_error: `Failed to fetch WhatsApp Integration: ${response.error.message || 'unknown error'}`
    }
  };
}

const integration = response.data || response.message || response;
const sheetRange = integration.google_sheet_range || 'Products!A1:J500';

return {
  json: {
    ...incoming,
    business_name: integration.business_name || '',
    phone_number_id: integration.phone_number_id || '',
    access_token: integration.access_token || '',
    gemini_api_key: integration.gemini_api_key || '',
    google_sheet_id: integration.google_sheet_id || '',
    google_sheet_range: sheetRange,
    google_sheet_range_encoded: encodeURIComponent(sheetRange),
    google_api_key: $env.GOOGLE_API_KEY || '',
    integration_doc: integration
  }
};

const context = $('Merge Integration Context').first().json;
const sheetResponse = $input.first()?.json || {};

const values = sheetResponse.values || sheetResponse.data?.values || [];
const headers = Array.isArray(values) && values.length > 0 ? values[0] : [];
const rows = Array.isArray(values) && values.length > 1 ? values.slice(1, 6) : [];

const products = rows.map((row) => {
  const record = {};
  headers.forEach((header, index) => {
    record[header] = row[index] ?? '';
  });
  return record;
});

const summary = products.length
  ? products.map((product, index) => {
      const name = product['Product Name'] || product['Name'] || product.product_name || 'Unknown product';
      const price = product['Price'] || product.price || '';
      const currency = product['Currency'] || product.currency || '';
      const stock = product['Stock'] || product.stock || '';
      const sku = product['SKU'] || product.sku || '';
      return `${index + 1}. ${name}${sku ? ` (SKU: ${sku})` : ''}${price ? ` - ${price}${currency ? ' ' + currency : ''}` : ''}${stock !== '' ? ` | Stock: ${stock}` : ''}`;
    }).join('\n')
  : 'No product catalog rows were returned.';

const prompt = `You are the WhatsApp assistant for ${context.business_name || 'this business'}.\nReply in a friendly, concise way and keep it under 150 words.\n\nCustomer name: ${context.customer_name || 'Unknown'}\nCustomer phone: ${context.customer_phone || 'Unknown'}\nMessage type: ${context.message_type || 'text'}\nCustomer message: ${context.customer_message || ''}\n${context.image_id ? `Image ID: ${context.image_id}\n` : ''}\nProduct catalog:
${summary}\n\nRules:
- Recommend only products from the catalog when relevant.\n- If the message is an image without a caption, ask the customer what they want help with.\n- If the catalog is empty, do not invent products.`;

return {
  json: {
    ...context,
    products_summary: summary,
    prompt
  }
};

