const context = $('Build Gemini Prompt').first().json;
const response = $input.first()?.json || {};

let aiResponse = 'Sorry, I could not generate a response right now. Please try again in a moment.';

if (!response.error) {
  const candidateText = response.candidates?.[0]?.content?.parts?.map((part) => part.text || '').join(' ').trim();
  if (candidateText) {
    aiResponse = candidateText;
  }
}

return {
  json: {
    ...context,
    ai_response: aiResponse,
    gemini_failed: Boolean(response.error),
    gemini_raw: response
  }
};

const context = $('Extract AI Reply').first().json;
const sendResult = $input.first()?.json || {};
const sentOk = !sendResult.error && (Array.isArray(sendResult.messages) ? sendResult.messages.length > 0 : Boolean(sendResult.messages || sendResult.id));

return {
  json: {
    ...context,
    whatsapp_sent_ok: sentOk,
    whatsapp_send_error: sendResult.error?.message || '',
    response_sent_at: new Date().toISOString()
  }
};

const context = $('Merge Integration Context').first().json;
return {
  json: {
    ok: false,
    error: context.workflow_error || 'Missing required WhatsApp integration config',
    message_id: context.message_id || '',
    integration: context.integration || ''
  }
};
